        p, mod = self.p, self.mod
        u %= mod
        if u == 0:
            return (0, 0)
        while u % p == 0:
            u //= p
            v += 1
            if u == 0:
                return (0, 0)
        return (u % mod, v)

    def from_int(self, k):
        return self.norm(k, 0)

    def add(self, A, B):
        ua, va = A
        ub, vb = B
        if ua == 0:
            return B
        if ub == 0:
            return A
        p = self.p
        v = va if va < vb else vb
        return self.norm(ua * p ** (va - v) + ub * p ** (vb - v), v)

    def neg(self, A):
        return (0, 0) if A[0] == 0 else ((-A[0]) % self.mod, A[1])

    def sub(self, A, B):
        return self.add(A, self.neg(B))

