            return 0
        if t[1] < 1:
            return None
        # t / p, reduced mod p
        return K.to_int((t[0], t[1] - 1)) % p

    pg = psi(G, 1)
    pq = psi(Q, 1)
    if not pg:
        return None
    return pq * pow(pg, -1, p) % p

